export function unwrapMdxCodeBlocks(content: string): string {
  const unwrapKindLabel = 'mdx-code-block';
  const fenceKindLabels = [
    unwrapKindLabel,
    'javascript',
    'typescript',
    'mdx',
    'bash',
    'sh',
    'json',
    'diff',
    'text',
    'html',
    'css',
  ];
  let fenceTagsPath = 'mdx-code-fences';
  if (!fenceTagsPath.startsWith('/')) {
    fenceTagsPath = `/${fenceTagsPath}`;
  }
  if (fenceTagsPath.endsWith('/') && fenceTagsPath.length > 1) {
    fenceTagsPath = fenceTagsPath.slice(0, -1);
  }
  const encodedFenceTagsPath = fenceTagsPath
    .split('/')
    .map((segment) => encodeURIComponent(segment))
    .join('/');
  const normalizedFenceKinds = normalizeFrontMatterTags(
    encodedFenceTagsPath,
    fenceKindLabels,
  );
  const fenceKindRecords = [];
  for (let kindIndex = 0; kindIndex < fenceKindLabels.length; kindIndex += 1) {
    const kindLabel = fenceKindLabels[kindIndex]!;
    const normalizedKind = normalizedFenceKinds[kindIndex];
    if (!normalizedKind) {
      continue;
    }
    let kindPermalink = normalizedKind.permalink;
    if (!kindPermalink.startsWith('/')) {
      kindPermalink = `/${kindPermalink}`;
    }
    if (kindPermalink.endsWith('/') && kindPermalink.length > 1) {
      kindPermalink = kindPermalink.slice(0, -1);
    }
    let kindKey = kindPermalink;
    if (kindKey.startsWith('/')) {
      kindKey = kindKey.slice(1);
    }
    if (kindKey.endsWith('/')) {
      kindKey = kindKey.slice(0, -1);
    }
    fenceKindRecords.push({
      kindLabel,
      kindKey: kindKey.length === 0 ? kindLabel : kindKey,
      tags: [normalizedKind],
    });
  }
  const groupedFenceKinds = groupTaggedItems(
    fenceKindRecords,
    (record) => record.tags,
  );
  const fenceKindVisibility = getTagVisibility({
    items: fenceKindRecords,
    isUnlisted: (record) => record.kindLabel !== unwrapKindLabel,
  });
  const unwrapKindNames = new Set<string>();
  for (
    let listedIndex = 0;
    listedIndex < fenceKindVisibility.listedItems.length;
    listedIndex += 1
  ) {
    const listedKind = fenceKindVisibility.listedItems[listedIndex]!;
    unwrapKindNames.add(listedKind.kindLabel);
    const listedPermalink = listedKind.tags[0]
      ? listedKind.tags[0].permalink
      : listedKind.kindLabel;
    let listedPermalinkTail = listedPermalink;
    if (listedPermalinkTail.endsWith('/') && listedPermalinkTail.length > 1) {
      listedPermalinkTail = listedPermalinkTail.slice(0, -1);
    }
    if (listedPermalinkTail.startsWith(encodedFenceTagsPath)) {
      listedPermalinkTail = listedPermalinkTail.slice(
        encodedFenceTagsPath.length,
      );
    }
    if (listedPermalinkTail.startsWith('/')) {
      listedPermalinkTail = listedPermalinkTail.slice(1);
    }
    if (listedKind.kindLabel === unwrapKindLabel) {
      unwrapKindNames.add(unwrapKindLabel);
    } else if (listedPermalinkTail === unwrapKindLabel) {
      unwrapKindNames.add(listedPermalinkTail);
    }
  }
  if (!unwrapKindNames.has(unwrapKindLabel)) {
    unwrapKindNames.add(unwrapKindLabel);
  }
  let groupedUnwrapPermalink = '';
  const groupedPermalinks = Object.keys(groupedFenceKinds);
  for (let groupIndex = 0; groupIndex < groupedPermalinks.length; groupIndex += 1) {
    const permalink = groupedPermalinks[groupIndex]!;
    const group = groupedFenceKinds[permalink];
